public class SchoolManagementTests { static void check(boolean condition,String message){if(!condition)throw new AssertionError(message);} static String grade(int score){if(score>=70)return "A";if(score>=60)return "B";if(score>=50)return "C";if(score>=45)return "D";return "F";} public static void main(String[] args){check("A".equals(grade(70)),"70 should be A");check("B".equals(grade(69)),"69 should be B");check("F".equals(grade(20)),"20 should be F");System.out.println("All SchoolManagementTests passed.");} }
